out = pathlib.Path(__file__).resolve().parent.parent / 'client' / 'src' / 'i18n'
def dump(idx, name, var):
    lines = ',\n'.join(f"  {json.dumps(k)}: {json.dumps(v[idx], ensure_ascii=False)}" for k, v in E.items())
    (out / name).write_text(f"// generated by scripts/i18n_enums.py\nexport const {var}: Record<string, string> = {{\n{lines}\n}};\n", encoding='utf-8')
dump(0, 'fr.base.ts', 'frBase'); dump(1, 'ar.base.ts', 'arBase')
print(len(E), 'enum keys written')
